/** What the operation came to (CP-25). */
export type ProvisionOutcome = "already_satisfied" | "completed" | "awaiting_permission" | "denied" | "failed" | "rolled_back" | "needs_recovery";

/** Install a capability of the catalog, or package specs, into an environment (CP-1). ``context.environment_id`` is the target: the session's own environment unless the agent names another of the project's. Either ``capability``, or package specs: Conda specs, or pip specs where conda-forge lacks a package (CP-15), with the reason. Conda and pip specs go in separate requests, the Conda ones first, so that pip resolves against the Conda packages once they are installed and never replaces them. System packages can never be installed at runtime (CP-5): naming them records the need, and the operation is denied. */
export interface ProvisionRequest {
  operation_id: string;
  context: ExecutionContext;
  purpose: string;
  capability: string | null;
  conda: string[];
  pip: string[];
  pip_reason: string | null;
  system: string[];
  action: "install" | "upgrade";
}

/** Where an operation is (CP-11): waiting for its turn, then each step in turn. */
export type ProvisionState = "queued" | "checking" | "resolving" | "awaiting_permission" | "installing" | "probing" | "finished";

